/// All queries, prepared once. Cheap to share behind an `Arc`.
///
/// Prefer this over the free functions when queries run repeatedly: each free
/// function prepares its statement on every call.
#[derive(Debug)]
pub struct Queries {
    session: ::std::sync::Arc<::scylla::client::session::Session>,
    get_user: ::scylla::statement::prepared::PreparedStatement,
    get_credentials: ::scylla::statement::prepared::PreparedStatement,
    create_user: ::scylla::statement::prepared::PreparedStatement,
    get_video: ::scylla::statement::prepared::PreparedStatement,
    add_video: ::scylla::statement::prepared::PreparedStatement,
    add_user_video: ::scylla::statement::prepared::PreparedStatement,
    videos_of_user: ::scylla::statement::prepared::PreparedStatement,
    add_latest_video: ::scylla::statement::prepared::PreparedStatement,
    latest_videos_of_day: ::scylla::statement::prepared::PreparedStatement,
    rate_video: ::scylla::statement::prepared::PreparedStatement,
    ratings_of_video: ::scylla::statement::prepared::PreparedStatement,
    count_playback: ::scylla::statement::prepared::PreparedStatement,
    playback_stats: ::scylla::statement::prepared::PreparedStatement,
}

impl Queries {
    /// Prepares every statement on `session`.
    pub async fn new(session: ::std::sync::Arc<::scylla::client::session::Session>) -> ::std::result::Result<Self, CqlcError> {
        let get_user = session.prepare(GET_USER_CQL).await.map_err(|e| CqlcError::new("GetUser", CqlcErrorKind::Prepare, e))?;
        let get_credentials = session.prepare(GET_CREDENTIALS_CQL).await.map_err(|e| CqlcError::new("GetCredentials", CqlcErrorKind::Prepare, e))?;
        let create_user = session.prepare(CREATE_USER_CQL).await.map_err(|e| CqlcError::new("CreateUser", CqlcErrorKind::Prepare, e))?;
        let get_video = session.prepare(GET_VIDEO_CQL).await.map_err(|e| CqlcError::new("GetVideo", CqlcErrorKind::Prepare, e))?;
        let add_video = session.prepare(ADD_VIDEO_CQL).await.map_err(|e| CqlcError::new("AddVideo", CqlcErrorKind::Prepare, e))?;
        let add_user_video = session.prepare(ADD_USER_VIDEO_CQL).await.map_err(|e| CqlcError::new("AddUserVideo", CqlcErrorKind::Prepare, e))?;
        let videos_of_user = session.prepare(VIDEOS_OF_USER_CQL).await.map_err(|e| CqlcError::new("VideosOfUser", CqlcErrorKind::Prepare, e))?;
        let add_latest_video = session.prepare(ADD_LATEST_VIDEO_CQL).await.map_err(|e| CqlcError::new("AddLatestVideo", CqlcErrorKind::Prepare, e))?;
        let latest_videos_of_day = session.prepare(LATEST_VIDEOS_OF_DAY_CQL).await.map_err(|e| CqlcError::new("LatestVideosOfDay", CqlcErrorKind::Prepare, e))?;
        let rate_video = session.prepare(RATE_VIDEO_CQL).await.map_err(|e| CqlcError::new("RateVideo", CqlcErrorKind::Prepare, e))?;
        let ratings_of_video = session.prepare(RATINGS_OF_VIDEO_CQL).await.map_err(|e| CqlcError::new("RatingsOfVideo", CqlcErrorKind::Prepare, e))?;
        let count_playback = session.prepare(COUNT_PLAYBACK_CQL).await.map_err(|e| CqlcError::new("CountPlayback", CqlcErrorKind::Prepare, e))?;
        let playback_stats = session.prepare(PLAYBACK_STATS_CQL).await.map_err(|e| CqlcError::new("PlaybackStats", CqlcErrorKind::Prepare, e))?;
        Ok(Queries { session, get_user, get_credentials, create_user, get_video, add_video, add_user_video, videos_of_user, add_latest_video, latest_videos_of_day, rate_video, ratings_of_video, count_playback, playback_stats })
    }

    /// The session the statements were prepared on.
    pub fn session(&self) -> &::scylla::client::session::Session {
        &self.session
    }

    pub async fn get_user(&self, userid: ::uuid::Uuid) -> ::std::result::Result<::std::option::Option<GetUserRow>, CqlcError> {
        get_user_with(&self.session, &self.get_user, userid).await
    }

    pub async fn get_credentials(&self, email: ::std::string::String) -> ::std::result::Result<::std::option::Option<GetCredentialsRow>, CqlcError> {
        get_credentials_with(&self.session, &self.get_credentials, email).await
    }

    pub async fn create_user(&self, params: CreateUserParams) -> ::std::result::Result<(), CqlcError> {
        create_user_with(&self.session, &self.create_user, params).await
    }

    pub async fn get_video(&self, videoid: ::uuid::Uuid) -> ::std::result::Result<::std::option::Option<GetVideoRow>, CqlcError> {
        get_video_with(&self.session, &self.get_video, videoid).await
    }

    pub async fn add_video(&self, params: AddVideoParams) -> ::std::result::Result<(), CqlcError> {
        add_video_with(&self.session, &self.add_video, params).await
    }

    pub async fn add_user_video(&self, params: AddUserVideoParams) -> ::std::result::Result<(), CqlcError> {
        add_user_video_with(&self.session, &self.add_user_video, params).await
    }

    pub async fn videos_of_user(&self, userid: ::uuid::Uuid) -> ::std::result::Result<::std::vec::Vec<VideosOfUserRow>, CqlcError> {
        videos_of_user_with(&self.session, &self.videos_of_user, userid).await
    }

    pub async fn stream_videos_of_user(&self, userid: ::uuid::Uuid) -> ::std::result::Result<::futures::stream::BoxStream<'static, ::std::result::Result<VideosOfUserRow, CqlcError>>, CqlcError> {
        stream_videos_of_user_with(&self.session, &self.videos_of_user, userid).await
    }

    pub async fn add_latest_video(&self, params: AddLatestVideoParams) -> ::std::result::Result<(), CqlcError> {
        add_latest_video_with(&self.session, &self.add_latest_video, params).await
    }

    pub async fn latest_videos_of_day(&self, yyyymmdd: ::std::string::String) -> ::std::result::Result<::std::vec::Vec<LatestVideosOfDayRow>, CqlcError> {
        latest_videos_of_day_with(&self.session, &self.latest_videos_of_day, yyyymmdd).await
    }

    pub async fn stream_latest_videos_of_day(&self, yyyymmdd: ::std::string::String) -> ::std::result::Result<::futures::stream::BoxStream<'static, ::std::result::Result<LatestVideosOfDayRow, CqlcError>>, CqlcError> {
        stream_latest_videos_of_day_with(&self.session, &self.latest_videos_of_day, yyyymmdd).await
    }

    pub async fn rate_video(&self, params: RateVideoParams) -> ::std::result::Result<(), CqlcError> {
        rate_video_with(&self.session, &self.rate_video, params).await
    }

    pub async fn ratings_of_video(&self, videoid: ::uuid::Uuid) -> ::std::result::Result<::std::vec::Vec<RatingsOfVideoRow>, CqlcError> {
        ratings_of_video_with(&self.session, &self.ratings_of_video, videoid).await
    }

    pub async fn stream_ratings_of_video(&self, videoid: ::uuid::Uuid) -> ::std::result::Result<::futures::stream::BoxStream<'static, ::std::result::Result<RatingsOfVideoRow, CqlcError>>, CqlcError> {
        stream_ratings_of_video_with(&self.session, &self.ratings_of_video, videoid).await
    }

    pub async fn count_playback(&self, videoid: ::uuid::Uuid) -> ::std::result::Result<(), CqlcError> {
        count_playback_with(&self.session, &self.count_playback, videoid).await
    }

    pub async fn playback_stats(&self, videoid: ::uuid::Uuid) -> ::std::result::Result<::std::option::Option<PlaybackStatsRow>, CqlcError> {
        playback_stats_with(&self.session, &self.playback_stats, videoid).await
    }
}

